'use strict';
const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a,pick=a=>a[rnd(0,a.length-1)],num=n=>Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n), money=n=>'$'+num(n), cap=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
const GENRES=['Pop','Pop-rock','Synth-pop','Dance-pop','Indie pop','Dream pop','Electropop','Country','Country-pop','Country rock','Americana','Folk','Indie folk','Alternative rock','Indie rock','Pop-punk','Soft rock','R&B','Alternative R&B','Soul','Hip-hop','Disco','Electronic','Acoustic','Jazz'], VIBES=['Dreamy','Confessional','Rebellious','Romantic','Dark','Playful','Nostalgic','Cinematic','Intimate','Euphoric'],MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'], FAN_CAP=200000000;
let s=null,tab='life',notice='',draft=freshDraft(),tourDraft={title:'',album:'',cities:[],venue:0,ticket:25},tourPreview=null;
function freshDraft(){return {id:uid('project'),kind:'album',title:'',concept:'',genres:['Pop'],vibe:'Dreamy',color:'#779de0',tracks:[],budget:1000,lead:0}}
function uid(prefix){return prefix+'-'+Math.random().toString(36).slice(2,10)}
function age(m=s.month){if(s.weekStart!==undefined&&typeof ageOnDayFor==='function')return ageOnDayFor(s,m===s.month?s.weekStart+6:firstWeekStartOfMonthFor(s.startYear,m)+6);return Math.floor((s.startYear*12+m-((s.birthYear??(s.startYear-s.startAge))*12+(s.birthMonth??0)))/12)}function year(m=s.month){return s.startYear+Math.floor(m/12)}function date(m=s.month){if(m===s.month&&s.weekStart!==undefined&&typeof weekDateLabel==='function')return weekDateLabel();return `${MONTHS[m%12]} ${year(m)} · Age ${age(m)}`}function log(title,text){s.log.unshift({month:s.month,title,text})}
function clamp(){for(const k of ['craft','voice','energy','happiness','rep','buzz'])s[k]=Math.round(cap(s[k]));s.fans=Math.round(cap(s.fans,0,FAN_CAP));s.cash=Math.round(Math.max(0,s.cash)*100)/100;s.prep=cap(s.prep,0,100);s.promo=cap(s.promo,0,60)}
function grow(n){const gained=Math.round(Math.max(0,n)*Math.pow(1-s.fans/FAN_CAP,2));s.fans=Math.min(FAN_CAP,s.fans+gained);return gained}
function change(v){for(let [k,n]of Object.entries(v||{})){if(k==='fans'&&n>0)grow(n);else{if(!Number.isInteger(n)&&['craft','voice','rep','buzz','energy','happiness'].includes(k)){let total=n+((s.fx||(s.fx={}))[k]||0),whole=Math.trunc(total);s.fx[k]=Math.round((total-whole)*1000)/1000;n=whole}s[k]=(s[k]||0)+n}}clamp()}
function modal(html){$('modal').innerHTML=html;$('modal').showModal()}function closeModal(){$('modal').close()}function say(text){notice=text;render()}function canAct(cost=0,energy=0){if(s.retired)return false;if(s.ap<1){say('No actions left this week. Resolve your event and move to the next week.');return false}if(s.cash<cost){say(`You need ${money(cost)} for this. Try a lower budget or earn some money first.`);return false}if(s.energy<energy){say('You need more energy. Take time off first.');return false}return true}
function help(){modal(`<h2>Your life. Your catalogue.</h2><p>Time advances week by week on real dates (Sunday to Saturday). You get <b>5 actions each week</b>. Each unused action restores 14 energy; a proper break costs $50 and restores 28; a week away restores full energy but uses 3 actions. Monthly statements, royalties and charts update when a new month begins. Resolve any life event, then advance whenever you are ready.</p><p>Start at age 12–30. Albums unlock at 14. Younger artists have guardian support and cheaper living costs. Build at least 20 preparation before releasing an album; wait 4 months between albums.</p><p>Choose an album (4–20 tracks), EP (3–6), or standalone single (1). Release songs early from a saved album or EP draft, then finish the project later. Blend up to 3 genres and keep one lead single. Singles and music videos also have their own audience and award opportunities.</p><p>Plan a tour at 1, 4, 8, 12 or 16 shows per month. The default is 8; adjust active tours from the Tours tab. Tours can have up to ${TOUR_MAX_STOPS} stops, split into legs with rest months between them, and tickets up to $${TOUR_TICKET_MAX}; you can also add your own cities. Ticket demand, venue size, performance and expenses determine profit—or loss.</p><p>Submit eligible work to eight fictional annual award shows. Deadline reminders appear when you have unsubmitted eligible categories. Press invitations arrive after career milestones; answer different questions in the Press tab. Lifestyle & investments offers equipment, campaigns and personal spending. Major career events begin around five years after your debut and are separated by roughly 4½–5½ years. The video planner previews quality, production value and preparation before spending. Nominations arrive one month before each ceremony; a nomination is not a guaranteed win.</p><p>Fans have diminishing growth and a ceiling of ${num(FAN_CAP)} unique fans. The Singer tab shows recording royalties, advance repayment and songwriting income separately. Half of your recording share remains payable during recoupment. Video allowances and supporter memberships help fund the career. These are game rules, not real-world royalty rates. This is a fictional simulation, not a forecast of the music industry.</p><p><b>Save game before closing.</b> Downloaded saves can be loaded here, including older Liner Notes saves. No real audio is generated.</p><button class="primary" onclick="closeModal()">Let's play</button>`)}
function setup(){ $('app').innerHTML=`<div class="setup"><div class="intro"><div class="eyebrow">LINER NOTES / EXPANDED EDITION</div><h1>Before the fame,<br>there was a song.</h1><p class="big muted">Write the music. Live the story. Build your own eras.</p></div><div class="card grid"><div><label>Stage name<input id="name" maxlength="35" placeholder="Your stage name"></label><div class="grid"><label>Birth month<select id="birthMonth" onchange="birthdayPreview()">${MONTHS.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Birth day<input type="number" id="birthDay" min="1" max="31" value="1" oninput="birthdayPreview()"></label><label>Birth year<input type="number" id="birthYear" min="1929" max="2088" value="2010" oninput="birthdayPreview()"></label><label>Starting year<input type="number" id="startYear" min="1960" max="2100" value="2026" oninput="birthdayPreview()"></label></div><p id="birthdayPreview" class="footnote">Your story begins in January 2026, aged 16. You age on your birthday month. Starting ages: 12–30.</p><label>Your world<select id="worldMode" onchange="worldModeHint()"><option value="" disabled selected>Choose your world</option><option value="fictional">Fictional — original artists</option><option value="realistic">Realistic — real artists, alternate history</option></select></label><p id="worldModeHint" class="footnote">Choose a world to see how its artists develop.</p><label>Your first sound<select id="genre">${GENRES.map(g=>`<option>${g}</option>`).join('')}</select></label><label>Starting chapter<select id="origin"><option value="bedroom">Bedroom songwriter</option><option value="stage">Local open-mic regular</option><option value="online">Online cover artist</option></select></label></div><div><h3>A blank page, on your terms.</h3><p class="muted">Start as early as 12, develop your sound, then release singles, EPs and albums from 14. Blend genres, plan tours and submit your best work for awards.</p><p class="muted">You begin with ${money(2500)} in music savings. Living costs rise when you turn 18. An audience takes time to build.</p><button class="primary" onclick="start()">Begin my story</button><div class="actions"><button onclick="loadGame()">Load game</button></div><small>Old saves supported · Fictional labels and award shows</small></div></div></div>`}
function start(){if(!['realistic','fictional'].includes($('worldMode')?.value))return modal('<p>Choose Realistic or Fictional before beginning your story.</p><button onclick="closeModal()">Back</button>');let y=Number($('startYear').value);if(!Number.isInteger(y)||y<1960||y>2100)return modal('<p>Choose a starting year between 1960 and 2100.</p><button onclick="closeModal()">Back</button>');let birthYear=Number($('birthYear').value),birthMonth=Number($('birthMonth').value),startingAge=Math.floor((y*12-birthYear*12-birthMonth)/12);if(!Number.isInteger(birthYear)||!Number.isInteger(birthMonth)||birthMonth<0||birthMonth>11||startingAge<12||startingAge>30)return modal('<p>Choose a valid birth month and year that make you 12–30 in January of your starting year.</p><button onclick="closeModal()">Back</button>');let birthDay=Number($('birthDay')?.value||1);if(!Number.isInteger(birthDay)||birthDay<1||birthDay>new Date(Date.UTC(birthYear,birthMonth+1,0)).getUTCDate())return modal('<p>Choose a birth day that exists in your birth month.</p><button onclick="closeModal()">Back</button>');let origin=$('origin').value;s={v:3,birthDay,weekStart:initialWeekStartFor(y),weekNum:0,worldMode:$('worldMode')?.value==='realistic'?'realistic':'fictional',name:$('name').value.trim()||'New Artist',startAge:startingAge,birthYear,birthMonth,startYear:y,month:0,ap:5,cash:2500,fans:origin==='online'?350:50,craft:origin==='bedroom'?45:30,voice:origin==='stage'?45:30,energy:85,happiness:75,rep:55,buzz:8,prep:0,promo:0,genre:$('genre').value,albums:[],contracts:[],deal:null,relationship:null,exes:[],met:[],candidates:[],awards:0,awardEntries:[],tours:[],log:[],usedEvents:[],trend:pick(GENRES),event:null,retired:false,lastRelease:-100,lastActions:{}};draft=freshDraft();draft.genres=[s.genre];tourDraft={title:'',album:'',cities:[],venue:0,ticket:25};tab='life';notice='';ensureCareer();log('The first page',`${s.name} begins at ${age()}, making ${s.genre.toLowerCase()} in ${year()}.`);makeEvent();render()}
function show(t){tab=t;notice='';render()}function btn(t,d,fn,disabled=false){return `<button class="choice" onclick="${fn}" ${disabled?'disabled':''}><strong>${esc(t)}</strong><small>${esc(d)}</small></button>`}
function render(){if(!s)return setup();ensureCareer();clamp();$('app').innerHTML=`<div class="layout"><aside><div class="card"><h3>${esc(s.name)} <span class="tag">✳</span><br><small>${esc(s.genre)} · ${s.fans>1000000?'Global star':s.fans>100000?'Established artist':s.fans>10000?'Rising artist':'Emerging artist'}</small></h3><div class="stat"><div class="row"><small>Energy</small><small>${s.energy}/100</small></div><div class="bar"><i style="width:${s.energy}%"></i></div></div><button class="compact" onclick="show('singer')">Artist profile & finances</button><div class="statsgrid"><div><small>YOUR MONEY</small><div class="number">${money(s.cash)}</div></div><div><small>UNIQUE FANS</small><div class="number">${num(s.fans)}</div></div><div><small>ALBUMS</small><div class="number">${fullAlbums().length}</div></div><div><small>AWARDS WON</small><div class="number">${s.awards}</div></div></div></div><small>${s.deal?esc(s.deal.name)+' · '+s.deal.left+' album(s) left':'Independent · Your future masters are yours'}<br>${s.relationship?(s.relationship.divorce?'Separated from ':s.relationship.stage==='Married'?'Married to ':s.relationship.stage==='Engaged'?'Engaged to ':'Dating ')+esc(s.relationship.name):'Single'}<br>Trending: ${esc(s.trend)}<br>Living costs: ${money(livingCost())}/month</small><div class="actions"><button onclick="saveGame()">Save game</button><button onclick="loadGame()">Load</button>${browserSaveControls()}</div><div class="actions"><button class="ghost" onclick="restart()">New life</button></div></aside><main><div class="row wrap"><div><div class="eyebrow">${date()}</div><h2 style="margin:6px 0">${s.retired?'The final track.':'Your next chapter.'}</h2></div><span class="pill">${s.ap} actions left</span></div>${eraBannerHTML()}<nav class="tabs">${[['life','Life'],['singer','Singer'],['education','Education'],['relationships','Relationships'],['industry','Industry'],['fanGrowth','Grow fans'],['online','Online Presence'],['press','Press & interviews'],['spending','Lifestyle & investments'],['studio','Studio'],['business','Record deals'],['tours','Tours'],['awards','Awards'],['charts','Billboard'],['catalogue','Discography'],['journal','Timeline']].map(([t,n])=>`<button class="${tab===t?'active':''}" onclick="show('${t}')">${n}</button>`).join('')}</nav>${careerNotices()}${notice?`<div class="notice" role="status">${esc(notice)}</div>`:''}<div id="view"></div></main></div>`;({life,singer,education,relationships,industry,fanGrowth,online,press,spending,studio,business,tours,awards,charts,catalogue,journal}[tab]||life)()}
const ACTIONS=[
['write','Write a new demo','Craft +3 · Preparation +8 · Energy −8','Creative work',0,8,{craft:3,prep:8,energy:-8},'A new demo captures something you have never quite said aloud.'],
['practice','Rehearse & vocal train','Performance +4 · Energy −10','Creative work',0,10,{voice:4,energy:-10},'You worked through a difficult passage until it felt natural.'],
['lesson','Take a music lesson','$120 · Craft +3, performance +3 · Energy −6','Creative work',120,6,{craft:3,voice:3,energy:-6},'Your teacher helped you hear where the melody could go.'],
['produce','Learn production','$80 · Preparation +12 · Craft +2 · Energy −10','Creative work',80,10,{prep:12,craft:2,energy:-10},'You built a production around the feeling of the song.'],
['cowrite','Co-write with a peer','$150 · Preparation +10 · Craft +3 · Energy −8','Creative work',150,8,{prep:10,craft:3,energy:-8},'A collaborator brought a perspective you would not have found alone.'],
['listen','Study an unfamiliar album','Craft +2 · Preparation +5','Creative work',0,0,{craft:2,prep:5},'You took notes on arrangement, pacing and the silences between songs.'],
['gig','Play a local show','Modest pay and new listeners · Energy −16','Career',0,16,null,''],
['work','Work a side job','Earn $450 (under 16: $100) · Energy −14 · Happiness −3','Career',0,14,null,''],
['social','Connect with fans','Small audience growth · Attention +4 · Energy −6','Career',0,6,null,''],
['promote','Build a release campaign','$250 · Campaign +8 · Attention +4 · Energy −5','Career',250,5,{promo:8,buzz:4,energy:-5},'A focused campaign gave listeners a reason to anticipate your music.'],
['network','Attend a music meetup','$50 · Reputation +2 · Attention +4 · Energy −8','Career',50,8,{rep:2,buzz:4,energy:-8},'You met musicians and organisers who remembered your songs.'],
['busk','Busk or play a community set','Earn $60–$140 · Performance +1 · Energy −12','Career',0,12,null,''],
['interview','Interviews & press invitations','Choose an outlet and answer questions about your career','Career',0,5,{rep:2,buzz:5,energy:-5},'You talked about the craft instead of feeding the rumour mill.'],
['rest','Take proper time off','Energy +28 · Happiness +8 · $50','Personal life',50,0,{energy:28,happiness:8},'You returned to the ordinary things that make the music possible.'],
['friends','Spend time with friends','$30 · Happiness +14 · Energy +8','Personal life',30,0,{happiness:14,energy:8},'Your friends reminded you who you are outside of your career.'],
['journal','Keep a private journal','Preparation +5 · Happiness +7','Personal life',0,0,{prep:5,happiness:7},'Some thoughts stayed private. Others might become songs someday.'],
['exercise','Go for a walk or exercise','Energy +12 · Happiness +5','Personal life',0,0,{energy:12,happiness:5},'You cleared your head without checking a single statistic.'],
['volunteer','Volunteer locally','Reputation +4 · Happiness +6 · Energy −8','Personal life',0,8,{rep:4,happiness:6,energy:-8},'You spent a day being useful without being the centre of attention.']];
function life(){let e=s.event;$('view').innerHTML=`${majorChapterPanel()}${s.retired?`<div class="card"><h2>Your legacy</h2><p>${releaseSummary()}. ${num(s.fans)} fans. ${s.awards} awards. ${money(s.cash)} saved.</p><p>Your music and timeline remain here to revisit.</p></div>`:e?`<div class="card event"><div class="eyebrow">${esc(e.type)}</div><h2 style="margin-top:12px">${esc(e.title)}</h2><p>${esc(e.text)}</p>${e.options.map((o,i)=>btn(o.label,o.hint,`decide(${i})`)).join('')}</div>`:`<div class="card"><h3>A little room to live.</h3><p class="muted">${s.usedEvents.length>20?'You have lived through plenty of headlines. Not every month needs another crisis.':'Use this month to develop your music and make time for your life.'}</p></div>`}${['Creative work','Career','Personal life'].map(group=>`<h3 class="section">${group}</h3><div class="grid">${ACTIONS.filter(a=>a[3]===group).map(a=>btn(a[1],a[2],`action('${a[0]}')`,(a[0]==='social'?ensureOnlineDesk().actions<1:s.ap<1)||s.retired)).join('')}</div>`).join('')}<div class="actions"><button class="primary" onclick="nextWeek()" ${s.event||s.retired?'disabled':''}>Next week</button><button class="ghost" onclick="retire()" ${s.retired?'disabled':''}>Retire from music</button></div><p><small>5 actions per month · Resolve your event first · Export your save before closing</small></p>`}
function action(k){if(k==='interview')return show('press');let a=ACTIONS.find(x=>x[0]===k);if(!a||!canAct(a[4],a[5]))return;s.ap--;s.cash-=a[4];let t=a[7];if(a[6])change(a[6]);if(k==='gig'){let pay=Math.round((60+s.voice*1.4+Math.min(450,Math.sqrt(s.fans)*.8))*ACTION_PAY_PACE);let f=grow(Math.max(1,Math.round((rnd(8,30)+s.voice*.6)*ACTION_FAN_PACE)));change({cash:pay,energy:-16,buzz:2*ACTION_PACE,voice:ACTION_PACE});t=`A local show earned ${money(pay)} after costs and brought ${num(f)} new fans.`}if(k==='work'){let pay=Math.round((age()<16?100:450)*ACTION_PAY_PACE);change({cash:pay,energy:-14,happiness:-3});t=`${age()<16?'Small chores and family-approved work':'A part-time shift'} earned ${money(pay)}.`}if(k==='social'){let f=grow(Math.max(1,Math.round((rnd(10,50)+Math.sqrt(s.fans)*.5)*ACTION_FAN_PACE)));change({energy:-6,buzz:4*ACTION_PACE});t=`An honest update reached ${num(f)} new fans.`}if(k==='busk'){let pay=Math.round(rnd(60,140)*ACTION_PAY_PACE),f=grow(Math.max(1,Math.round(rnd(5,25)*ACTION_FAN_PACE)));change({cash:pay,voice:ACTION_PACE,energy:-12});t=`Your community set earned ${money(pay)} and ${f} new fans.`}equipmentBonus(k);s.lastActions[k]=s.month;log(a[1],t);say(t)}
const NAMES=['Alex','Jamie','Morgan','Riley','Casey','Jordan','Taylor','Avery','Sam','Robin','Charlie','Quinn','Rowan','Harper','Elliot','Sasha','Reese','Cameron','Drew','Skyler','Emery','Jules','Blair','Noel','River','Dakota','Parker','Finley','Hayden','Remy'];
const BIOS=['an amateur photographer who likes quiet cafés','a pianist with a dry sense of humour','a film lover who remembers every detail','a book lover who enjoys long walks','a dancer who makes time for friends','a songwriter with a very different sound','a keen baker who avoids celebrity gossip','a sports enthusiast who loves your acoustic demos','an artist who collects old postcards','a theatre fan who always has a story'];
function meetPeople(){if(age()<14||!canAct())return;s.ap--;let pool=NAMES.filter(n=>!s.met.includes(n));if(pool.length<3)pool=NAMES.filter(n=>!s.candidates.some(p=>p.name===n));s.candidates=[];for(let i=0;i<3;i++){let n=pick(pool);pool=pool.filter(x=>x!==n);s.met.push(n);s.candidates.push({name:n,ageAtMeet:age(),since:s.month,bio:pick(BIOS),bond:55,lastDate:s.month})}log('New company','You met a few people your age through mutual friends.');say('Choose someone to get to know—or stay single. Meeting people used one action; choosing does not cost another.')}
function choosePartner(i){if(s.retired||s.relationship||!s.candidates[i])return;let p=s.candidates[i];s.relationship={...p,ageAtMeet:age(),since:s.month,lastDate:s.month};s.candidates=[];change({happiness:10});log('A new relationship',`You and ${p.name} decided to give this a chance.`);say(`You are now dating ${p.name}.`) }
function datePartner(){if(!s.relationship||!canAct(40))return;s.ap--;s.cash-=40;s.relationship.bond=cap(s.relationship.bond+18);s.relationship.lastDate=s.month;change({happiness:10,energy:6});log('Time together',`You made space for ${s.relationship.name} this month.`);say('Closeness +18. Sometimes the best chapter stays out of the headlines.')}
function breakup(){if(s.relationship?.stage==='Married')return requestDivorce();if(!s.relationship||!canAct())return;modal(`<h2>End things with ${esc(s.relationship.name)}?</h2><p>This relationship will become part of your history. You can meet someone new later.</p><div class="actions"><button onclick="confirmBreakup()">End the relationship</button><button onclick="closeModal()">Stay together</button></div>`)}
function confirmBreakup(){if(!s.relationship||s.ap<1)return;s.ap--;let n=s.relationship.name;s.exes.push({...s.relationship,end:s.month});s.relationship=null;change({happiness:-10,prep:10});log('A chapter closes',`You and ${n} parted ways.`);closeModal();say('The relationship ended. Take time for yourself, or meet new people when you are ready.')}
// Each authored event can occur once per career. A quiet month is preferable to rerunning a scandal.
const EV=[];
function addEvent(id,type,title,text,options,minAge=12,minFans=0){EV.push({id,type,title,text,options:options.map(o=>({label:o[0],hint:o[1],v:o[2],out:o[3]})),minAge,minFans})}
addEvent('firstdemo','FIRST STEPS','Someone wants to hear a song.','A friend asks you to play something you wrote. Nobody has heard these lyrics yet.',[['Play the unfinished demo','Craft +3 · Confidence through practice',{craft:3,happiness:3},'You played the song, shaky voice and all. Your friend asked to hear it again.'],['Work on it privately first','Preparation +8',{prep:8},'You kept the song close and gave its second verse more care.']]);
addEvent('schoolshow','EARLY YEARS','A stage between lessons.','A school or community showcase needs one more performer.',[['Try an original','Performance +4 · Fans +25',{voice:4,fans:25,energy:-6},'A few listeners remembered the chorus afterwards.'],['Choose a familiar cover','Performance +2 · Happiness +5',{voice:2,happiness:5},'A familiar melody helped you feel at home on stage.']]);
addEvent('host','INTERVIEW','“Who is this song really about?”','A host presses you to name the person behind your writing.',[['Protect their identity','Reputation +6 · Attention −2',{rep:6,buzz:-2},'You drew a boundary without making a scene.'],['Tell the story without naming names','Attention +5 · Happiness −3',{buzz:5,happiness:-3},'People connected with the feeling, then started guessing anyway.'],['Make a joke','Attention +4',{buzz:4},'Your quick answer became the clip people shared.']],14,1000);
addEvent('clip','SCANDAL','A backstage clip goes viral.','An edited video makes it look like you brushed off a listener.',[['Post the full context','Reputation +8',{rep:8},'The full interaction changed how many viewers understood it.'],['Clap back','Attention +12 · Reputation −9',{buzz:12,rep:-9},'Your reply became a bigger story than the original clip.'],['Stay offline','Energy +8 · Reputation −4',{energy:8,rep:-4},'The noise faded, though not everyone saw your side.']],14,3000);
addEvent('notebook','CREATIVE CHOICE','The obvious hit—or the strange one?','A catchy chorus is working. Your most unusual demo is more personal.',[['Follow the unusual idea','Craft +5 · Preparation +8',{craft:5,prep:8},'The arrangement took you somewhere unexpected.'],['Polish the hook','Preparation +10 · Attention +3',{prep:10,buzz:3},'You sharpened every line until the chorus landed immediately.']]);
addEvent('birthday','FRIENDSHIP','Two invitations. One evening.','A music mixer falls on your closest friend’s birthday.',[['Choose the birthday','Happiness +10',{happiness:10},'Your friend saved you a seat.'],['Attend the mixer','Attention +6 · Happiness −5',{buzz:6,happiness:-5},'You made useful introductions, but missed an important evening.']]);
addEvent('rival','RIVALRY','A pointed comment.','A musician suggests that your songs are too calculated.',[['Share an early voice memo','Reputation +5 · Fans +80',{rep:5,fans:80},'The unpolished recording let your process speak for itself.'],['Write a response song','Preparation +10 · Attention +8 · Reputation −4',{prep:10,buzz:8,rep:-4},'The response gave you a sharp new song and an uncomfortable new rivalry.'],['Let the work stand','Happiness +4',{happiness:4},'You decided you did not need to answer every opinion.']],14,1500);
addEvent('festival','OPPORTUNITY','An afternoon festival slot.','A small festival has space before the headliners arrive.',[['Play a welcoming set','Fans +120 · Energy −12',{fans:120,voice:2,energy:-12},'People drifted toward the stage as your set unfolded.'],['Test new songs','Preparation +12 · Energy −8',{prep:12,energy:-8},'You learned which new songs could hold a room.']],14,500);
addEvent('brand','SPONSORSHIP','An uncomfortable endorsement.','A brand you rarely use offers a small paid campaign.',[['Take the deal','Money +$900 · Reputation −5',{cash:900,rep:-5},'It paid for studio time, though some listeners found it unconvincing.'],['Decline politely','Reputation +4',{rep:4},'You kept your name off a product you could not stand behind.']],16,5000);
addEvent('oldpost','SCANDAL','An old joke resurfaces.','A careless old post is circulating. You no longer agree with it.',[['Own it and apologise','Reputation +4 · Happiness −4',{rep:4,happiness:-4},'Your apology was direct. Forgiveness took longer.'],['Dismiss the criticism','Attention +10 · Reputation −14',{buzz:10,rep:-14},'The response gave the controversy another week of life.'],['Delete it quietly','Reputation −6',{rep:-6},'Screenshots survived the deletion.']],16,10000);
addEvent('lostdemo','STUDIO TROUBLE','The file will not open.','A promising demo has become corrupted. You remember most of it.',[['Rebuild from memory','Preparation +7 · Energy −8',{prep:7,energy:-8},'The rebuilt version took a different, unexpectedly better turn.'],['Start something new','Craft +3',{craft:3},'You let go of the original and followed a new melody.']]);
addEvent('rain','A QUIET DAY','Rain at the window.','Your afternoon plans disappear under a thunderstorm.',[['Write through it','Preparation +7',{prep:7},'The rain found its way into the rhythm of a new demo.'],['Do nothing for once','Energy +12 · Happiness +4',{energy:12,happiness:4},'You watched the weather without trying to turn it into content.']]);
addEvent('family','FAMILY','“What is the backup plan?”','Someone at home worries about how much you are investing in music.',[['Explain a realistic plan','Reputation +3 · Happiness +4',{rep:3,happiness:4},'A clear plan eased the conversation.'],['Avoid the conversation','Energy +4 · Happiness −3',{energy:4,happiness:-3},'The subject changed, but the concern did not.']]);
addEvent('lyric','SONGWRITING','A line that might hurt someone.','One lyric is honest—but makes a private argument recognisable.',[['Change the identifying details','Craft +3 · Reputation +4',{craft:3,rep:4},'The emotion remained even after the details changed.'],['Keep the line','Preparation +8 · Happiness −5',{prep:8,happiness:-5},'It was a powerful lyric. Living with it was harder.']],14);
