addEvent('instrument','NEW SOUNDS','An unfamiliar instrument.','A friend lends you an instrument you have never written with.',[['Experiment with it','Craft +4 · Preparation +5',{craft:4,prep:5},'Different shapes under your fingers led to different melodies.'],['Stick with what works','Preparation +8',{prep:8},'You finished a song using the tools you already knew well.']]);
addEvent('duet','COLLABORATION','A peer proposes a duet.','Their sound is nothing like yours. That might be the point.',[['Try the collaboration','Craft +4 · Fans +50',{craft:4,fans:50},'Neither of you would have written this alone.'],['Share ideas without releasing','Preparation +8',{prep:8},'The session stayed private but opened a new direction.']]);
addEvent('review','FIRST REVIEWS','“Promising, but uneven.”','A small reviewer praises your voice and questions your arrangements.',[['Take the useful criticism','Craft +5',{craft:5},'You found a practical lesson inside a difficult read.'],['Protect your confidence','Happiness +6',{happiness:6},'You closed the review and returned to a song you loved.']],14,500);
