addEvent('tickets','FAN RELATIONS','A listener cannot afford the ticket.','Someone writes about wanting to hear you live but having no spare money.',[['Put them on a guest list','Money −$25 · Reputation +5',{cash:-25,rep:5},'You made room for one more person in the audience.'],['Share a free live session','Energy −5 · Fans +50',{energy:-5,fans:50},'The recording reached people who could not be in the room.']],14,300);
addEvent('rumour','RUMOURS','A friendship becomes a headline.','A photo with another musician sparks dating speculation.',[['Say you are friends','Reputation +3',{rep:3},'You kept the answer simple.'],['Decline to discuss your private life','Happiness +5 · Attention +3',{happiness:5,buzz:3},'You did not owe strangers every detail.']],16,20000);
addEvent('playlist','DISCOVERY','A niche playlist notices you.','A curator wants a short story about how you wrote your music.',[['Record a thoughtful introduction','Fans +200 · Energy −5',{fans:200,energy:-5},'The introduction gave new listeners a way into your songs.'],['Send a short written note','Fans +80 · Preparation +3',{fans:80,prep:3},'A few words helped the song find the right listeners.']],14,1000);
addEvent('wardrobe','VISUAL IDENTITY','The look does not feel like you.','A stylist suggests an image that is striking but uncomfortable.',[['Build the look together','Reputation +3 · Happiness +4',{rep:3,happiness:4},'You found an image you could inhabit.'],['Try the dramatic change','Attention +7 · Happiness −3',{buzz:7,happiness:-3},'The photos got attention. You were still deciding how they felt.']],14,3000);
addEvent('hometown','HOMETOWN','They remember your first show.','A local organiser invites you back to where you started.',[['Play a stripped-back set','Performance +3 · Happiness +8',{voice:3,happiness:8},'Old faces sang along with new songs.'],['Send a personal video message','Reputation +3 · Energy +3',{rep:3,energy:3},'You found a way to acknowledge the people who encouraged you early.']],14,3000);
addEvent('credit','CREDITS','A collaborator asks for credit.','A friend contributed an important melodic idea during a casual session.',[['Acknowledge the contribution','Reputation +6 · Happiness +2',{rep:6,happiness:2},'Clear credit protected both the friendship and the song.'],['Offer a new joint session','Preparation +10 · Energy −8',{prep:10,energy:-8},'You discussed expectations and wrote something together from the start.']]);
addEvent('comparison','PRESS','“The next big version of someone else.”','An article compares you to a famous artist instead of discussing your songs.',[['Point to your own influences','Reputation +4 · Craft +2',{rep:4,craft:2},'You described the different records that shaped your writing.'],['Take the exposure graciously','Fans +150 · Attention +4',{fans:150,buzz:4},'New listeners arrived through the comparison and stayed for your music.']],14,6000);
addEvent('burnout','HEALTH & BALANCE','Everything sounds flat today.','You have been measuring every day by its productivity.',[['Take a day with no music','Energy +18 · Happiness +7',{energy:18,happiness:7},'Rest did not solve everything, but it made room for feeling again.'],['Change the setting','Energy +8 · Preparation +5',{energy:8,prep:5},'A different room helped you hear the song differently.']]);
addEvent('leak','SECURITY','An unfinished snippet leaks.','A rough mix escapes your private circle.',[['Explain that it is a work in progress','Reputation +3 · Attention +5',{rep:3,buzz:5},'You set expectations without pretending the recording did not exist.'],['Go quiet and finish the song','Preparation +12 · Happiness −4',{prep:12,happiness:-4},'You reclaimed the song by finishing it on your own terms.']],14,10000);
addEvent('contest','EARLY OPPORTUNITY','A songwriting competition.','A community contest asks for a short original performance.',[['Enter for the experience','Performance +3 · Fans +30',{voice:3,fans:30},'The useful part was learning to finish and deliver a song on time.'],['Help a friend rehearse instead','Happiness +8 · Craft +2',{happiness:8,craft:2},'Helping someone else revealed something about your own writing.']]);
addEvent('arrange','ARRANGEMENT','The song might need less.','The demo has layers everywhere, but the voice is getting lost.',[['Strip it back','Craft +4 · Preparation +6',{craft:4,prep:6},'Without the extra layers, the lyric finally landed.'],['Rebuild around a stronger beat','Preparation +10 · Energy −5',{prep:10,energy:-5},'A new groove gave the arrangement a purpose.']]);
addEvent('vinyl','FAN REQUEST','“Will there be a physical edition?”','A small group of listeners asks for something they can keep.',[['Share a printable lyric booklet','Reputation +3 · Fans +40',{rep:3,fans:40},'A modest extra meant a lot to the listeners who wanted it.'],['Explain you are saving for the next record','Reputation +2 · Happiness +3',{rep:2,happiness:3},'Honesty about your budget helped people understand the decision.']],14,2000);
addEvent('travel','INSPIRATION','A place you have never been.','A short trip gives you unfamiliar streets and hours away from routine.',[['Write observations in your notebook','Preparation +8 · Craft +2',{prep:8,craft:2},'A few details from the trip became the setting of a song.'],['Keep the trip just for yourself','Happiness +10',{happiness:10},'The memory did not need to become part of your public story.']]);
addEvent('charity','COMMUNITY','A benefit concert needs help.','A local cause asks you to lend a song to its event.',[['Perform a short set','Reputation +5 · Energy −8',{rep:5,energy:-8},'Your music became useful to a cause beyond your career.'],['Help behind the scenes','Happiness +8 · Reputation +2',{happiness:8,rep:2},'Nobody needed you in the spotlight for your help to matter.']]);
addEvent('voice','PERFORMANCE','A cracked note.','A rehearsal recording catches your voice breaking on the final phrase.',[['Adjust the key','Performance +4',{voice:4},'You found the range in which the emotion sounded natural.'],['Practise a gentler interpretation','Performance +3 · Craft +2',{voice:3,craft:2},'The quieter version was more convincing than forcing the note.']]);
addEvent('mentor','MENTORSHIP','A musician makes time for you.','An experienced songwriter offers to listen to two demos.',[['Bring the song you cannot finish','Preparation +12',{prep:12},'One practical suggestion unlocked the second half of the song.'],['Ask about surviving the industry','Reputation +3 · Happiness +5',{rep:3,happiness:5},'Their advice was less glamorous and more useful than you expected.']]);
addEvent('deepcut','LISTENERS','They chose the deep cut.','Listeners are discussing an overlooked track more than your obvious crowd-pleaser.',[['Talk about its story','Fans +160 · Attention +4',{fans:160,buzz:4},'The song found its audience on its own terms.'],['Let listeners interpret it','Reputation +3 · Happiness +4',{rep:3,happiness:4},'You enjoyed hearing meanings you had never intended.']],14,2500);
addEvent('fanart','FAN COMMUNITY','Someone drew your song.','A listener sends a piece of art inspired by your writing.',[['Share it with permission and credit','Reputation +4 · Fans +50',{rep:4,fans:50},'The artist was glad you asked before sharing it.'],['Send a private thank-you','Happiness +7',{happiness:7},'The exchange stayed small and personal.']],14,300);
addEvent('headline','INTERVIEW','The headline leaves out half the answer.','A thoughtful interview gets reduced to its most provocative sentence.',[['Ask for a factual correction','Reputation +4',{rep:4},'The outlet added the missing context.'],['Publish the longer answer yourself','Attention +6 · Energy −5',{buzz:6,energy:-5},'Some readers took the time to hear what you actually meant.']],16,15000);
addEvent('invitation','CAREER','A support slot opens up.','A touring act offers you a brief set at a nearby show.',[['Accept and prepare carefully','Performance +3 · Fans +250 · Energy −12',{voice:3,fans:250,energy:-12},'You won over a small part of a room that came for someone else.'],['Keep your current commitments','Reputation +3 · Energy +5',{rep:3,energy:5},'You chose to do the things you had already promised well.']],14,2500);
addEvent('money','BUDGET','The expensive microphone.','A studio advert insists one purchase will transform your recordings.',[['Use what you already have','Preparation +5',{prep:5},'A better performance did more than another piece of equipment.'],['Spend time learning microphone technique','Performance +3 · Preparation +4',{voice:3,prep:4},'You improved the sound by understanding the tools.']]);
addEvent('bridge','WRITING BLOCK','The bridge goes nowhere.','You have tried six versions and all of them sound forced.',[['Remove the bridge entirely','Craft +3 · Preparation +5',{craft:3,prep:5},'The song did not need the section you kept trying to give it.'],['Put the song away for a week','Energy +10 · Happiness +3',{energy:10,happiness:3},'Distance helped you hear the rest of the record again.']]);
addEvent('trend','REINVENTION','The trend has moved on.','The sound filling playlists is changing faster than your album plans.',[['Commit to this record’s identity','Craft +4 · Preparation +7',{craft:4,prep:7},'You gave this chapter a coherent ending before chasing the next one.'],['Test a new hybrid sound','Craft +5 · Attention +3',{craft:5,buzz:3},'The experiment found a link between your old sound and a new influence.']],14,1000);
addEvent('boundary','FAME','Someone follows you after a show.','An enthusiastic listener keeps asking for access to your private plans.',[['State a clear boundary','Reputation +3 · Happiness +5',{rep:3,happiness:5},'You were polite and firm about where the performance ended.'],['Ask the organiser for support','Energy +6 · Happiness +4',{energy:6,happiness:4},'You did not have to manage the situation alone.']],14,5000);
addEvent('setlist','LIVE MUSIC','The set needs a surprise.','Your familiar songs work, but the middle of the set feels predictable.',[['Rearrange an old song','Performance +4 · Preparation +4',{voice:4,prep:4},'An old chorus felt new with a different arrangement.'],['Add a quiet acoustic moment','Performance +3 · Happiness +4',{voice:3,happiness:4},'Silence became part of the set’s momentum.']],14);
addEvent('archive','MEMORY','An old notebook turns up.','Between unfinished homework and doodles, you find your earliest lyrics.',[['Rewrite one with what you know now','Craft +4 · Preparation +6',{craft:4,prep:6},'You kept the old feeling and found better words for it.'],['Keep it as a private memory','Happiness +10',{happiness:10},'Not every early attempt needed to be improved.']]);
addEvent('gratitude','PERSONAL LIFE','A message from an old teacher.','Someone who encouraged your first attempts asks how you are doing.',[['Write an honest reply','Happiness +8',{happiness:8},'It helped to describe the journey to someone who remembered its beginning.'],['Send a new demo','Preparation +5 · Happiness +4',{prep:5,happiness:4},'Their reply was enthusiastic without asking about the numbers.']]);
addEvent('accusation','SCANDAL','Two melodies sound similar.','A listener points out a resemblance between your demo and an older song.',[['Review it and revise the phrase','Craft +4 · Reputation +5',{craft:4,rep:5},'A careful revision protected the song without pretending you were above influence.'],['Explain the shared musical idea calmly','Reputation +2 · Attention +4',{rep:2,buzz:4},'The conversation became more specific and less heated.']],14,10000);
addEvent('success','EXPECTATIONS','“Do that again.”','After a good response, people expect your next work to repeat the formula.',[['Give yourself permission to change','Craft +5 · Happiness +4',{craft:5,happiness:4},'You decided a successful song did not have to become a permanent template.'],['Explore what made it work','Preparation +10',{prep:10},'You studied the connection rather than copying the surface.']],14,15000);
addEvent('celebration','PERSPECTIVE','An ordinary good evening.','There is no crisis, no launch, no headline. Friends invite you over.',[['Go and leave your phone away','Happiness +12 · Energy +6',{happiness:12,energy:6},'For one evening, your life was bigger than your career.'],['Stay home with a record you love','Energy +12 · Craft +2',{energy:12,craft:2},'You remembered why you wanted to make music in the first place.']]);
function careerEvent(){
 let careerAlbums=fullAlbums(),album=careerAlbums[0];
 const make=(id,type,title,text,options)=>({id,type,title,text,options:options.map(o=>({label:o[0],hint:o[1],v:o[2],out:o[3]}))});
 let moments=[];
 if(album&&s.month>album.month&&s.month-album.month<8){
  if(careerAlbums.length===1)moments.push(make('milestone-debut','YOUR FIRST ERA','The first record is real.',`A listener tells you that ${album.title} helped them describe something they could not put into words.`,[['Reply personally','Happiness +10 · Reputation +3',{happiness:10,rep:3},'Your first album began to mean something outside your own life.'],['Keep their message in your notebook','Preparation +8',{prep:8},'You kept the reminder of why the details matter.']]));
  if(careerAlbums.length===2)moments.push(make('milestone-sophomore','THE SECOND ALBUM','They are comparing your two records.',`Some listeners prefer the debut. Others say ${album.title} is where you found your voice.`,[['Give both records room to exist','Reputation +5 · Happiness +5',{rep:5,happiness:5},'You did not need to disown your beginning to grow beyond it.'],['Explain the new direction','Attention +7 · Craft +2',{buzz:7,craft:2},'You helped listeners understand what changed between the two chapters.']]));
  if(careerAlbums.length===3)moments.push(make('milestone-third','ARTISTIC IDENTITY','A pattern is becoming a body of work.',`With ${album.title}, reviewers are starting to discuss your career rather than just one release.`,[['Lean into the through-line','Craft +5 · Reputation +3',{craft:5,rep:3},'You recognised themes you had been returning to for years.'],['Challenge yourself to break the pattern','Preparation +12',{prep:12},'Your next notebook started somewhere deliberately unfamiliar.']]));
  if(careerAlbums.length>=4)moments.push(make('milestone-catalogue','YOUR CATALOGUE','The early songs have aged with you.',`New fans discovering ${album.title} are going back through your earlier records.`,[['Talk about what you would write differently','Craft +4 · Reputation +4',{craft:4,rep:4},'You spoke honestly about growth without belittling your younger self.'],['Let the old work stand on its own','Happiness +8',{happiness:8},'The records remained honest snapshots of different versions of you.']]));
 }
 if(s.tours.some(t=>t.status==='Completed'))moments.push(make('milestone-tour','AFTER THE TOUR','Home sounds unusually quiet.','After a completed tour, the routines of ordinary life feel unfamiliar.',[['Reconnect with the people at home','Happiness +12 · Energy +10',{happiness:12,energy:10},'You found a rhythm that did not depend on the next soundcheck.'],['Write down the road stories','Preparation +15 · Energy −5',{prep:15,energy:-5},'A collection of cities became a collection of song ideas.']]));
 if(age()>=18)moments.push(make('milestone-adult','GROWING UP','The decisions are becoming yours.','You are learning to manage a career and an ordinary adult life at the same time.',[['Set a budget and protect your time','Happiness +7 · Reputation +3',{happiness:7,rep:3},'A practical routine gave your creative work more room.'],['Make a plan for the person you want to become','Preparation +8 · Happiness +4',{prep:8,happiness:4},'Your plans started to include a life beyond the next release.']]));
 if(s.awards>0)moments.push(make('milestone-award','AFTER THE WIN','The trophy is on the shelf.','The ceremony is over. Your next blank page is still blank.',[['Go back to a small, personal song','Craft +5 · Preparation +6',{craft:5,prep:6},'You followed curiosity instead of trying to reproduce an award.'],['Celebrate before going back to work','Happiness +12 · Energy +8',{happiness:12,energy:8},'You let the moment be enough for a while.']]));
 return moments.find(e=>!s.usedEvents.includes(e.id));
}
function toggleGenre(g,checked){if(checked&&draft.genres.length<3&&!draft.genres.includes(g))draft.genres.push(g);else if(!checked&&draft.genres.length>1)draft.genres=draft.genres.filter(x=>x!==g);studio()}
function inspire(){let titles=['Last Train Home','Glass House','Blue Hour','Your Side of the City','Paper Crown','After the Applause','Nothing Like Forever','October Again','A Better Goodbye','Neon Weather','Keep the Receipts','The Quiet Part','Borrowed Summer','Half a Heartbeat','Soft Landing','Velvet Static','Lavender Weather','Room for Two','No Forwarding Address','Exit Music','In Another Light'];let pool=titles.filter(t=>!draft.tracks.some(x=>x.title===t));$('trackname').value=pool.length?pick(pool):pick(['Silver','Midnight','Empty','Golden'])+' '+pick(['Windows','Promises','Letters','Roads'])}
function releaseSingle(i,j){let a=s.albums[i],t=a?.tracks[j];if(!t||t.single||!canAct(0,8))return;s.ap--;change({energy:-8,buzz:5});t.single=true;t.singleSince=s.month;t.released??=a.month;t.audience=null;t.firstStreams=Math.round(Math.min(5000000,300+Math.pow(s.fans,.78)*10)*(t.quality/70)*rnd(55,155)/100);let rawSingle=t.firstStreams;if(typeof digitalListening==='function')t.firstStreams=digitalListening(a,t,rawSingle);t.audience=audienceProfile(rawSingle,s.month);t.total=(t.total||0)+t.firstStreams;a.total+=t.firstStreams;a.pendingStreams=(a.pendingStreams||0)+t.firstStreams;a.singleTail=(a.singleTail||0)+t.firstStreams*.2;addChartReach(a,t,t.firstStreams);let f=planReleaseGrowth(t.firstStreams*.4,t.quality,'single');log('A new single',`${t.title} from ${a.title}: ${launchText(t.firstStreams,a)}, and about ${num(f)} new fans over the coming weeks.`);say(`${t.title} is now a single. Submit it for eligible song awards.`)}
function changeLead(i,j){if(s.retired)return;let a=s.albums[i];if(!a?.tracks[j]?.single)return;a.lead=j;log('Campaign focus',`${a.tracks[j].title} is now the lead single for ${a.title}.`);say('Lead single updated. Existing singles and their results remain intact.')}
const DEALS=[{name:'Little Lantern Records',advance:5000,royalty:.65,left:2,masters:true,reach:1.35,min:0},{name:'Northstar Music',advance:20000,royalty:.3,left:3,masters:false,reach:1.9,min:5000},{name:'Empire Sound Group',advance:75000,royalty:.2,left:4,masters:false,reach:2.6,min:50000}];
function buyout(){if(!s.deal||s.retired)return;if(s.deal.buyout===0)return say('This contract has no buyout clause. Complete your albums to leave.');let cost=buyoutCost(s.deal);if(s.cash<cost)return say('You do not have enough money for this buyout.');modal(`<h2>Leave ${esc(s.deal.name)}?</h2><p>Pay ${money(cost)} to clear this advance and future album obligations. Existing royalty splits and master ownership will remain.</p><button onclick="confirmBuyout()">Confirm buyout</button> <button onclick="closeModal()">Cancel</button>`)}function confirmBuyout(){if(!s.deal||s.deal.buyout===0)return;let cost=buyoutCost(s.deal);if(s.cash<cost)return;s.cash-=cost;log('Independent again',`You paid ${money(cost)} to end your future obligation to ${s.deal.name}.`);s.deal.recoup=0;s.deal=null;closeModal();say('Your future recordings are independent again.')}
const CITIES=[['Singapore','Asia',1],['Tokyo','Asia',1.2],['Seoul','Asia',1.1],['Manila','Asia',1],['Bangkok','Asia',.9],['Sydney','Oceania',.9],['Melbourne','Oceania',.9],['London','Europe',1.3],['Paris','Europe',1],['Berlin','Europe',.9],['Amsterdam','Europe',.85],['Copenhagen','Europe',.75],['New York','North America',1.3],['Los Angeles','North America',1.3],['Nashville','North America',.9],['Chicago','North America',1],['Toronto','North America',1],['Vancouver','North America',.8],['Mexico City','Latin America',1],['São Paulo','Latin America',1.1],['Buenos Aires','Latin America',.9],['Cape Town','Africa',.7]];
const VENUES=[{name:'Small club',cap:150,base:180},{name:'Music hall',cap:600,base:650},{name:'Theatre',cap:1800,base:2000},{name:'Arena',cap:12000,base:22000},{name:'Stadium',cap:45000,base:110000}];
function planEra(i){tourDraft.album=s.albums[i].id;tourDraft.title=s.albums[i].title+' Tour';tab='tours';notice='';render()}
function tours(){registerCustomCities();ensureTourLegs();let releaseOptions=collections();if(!releaseOptions.some(a=>a.id===tourDraft.album))tourDraft.album=releaseOptions[0]?.id||'';let active=s.tours.find(t=>t.status==='Active');$('view').innerHTML=`${active?`<div class="card event"><div class="eyebrow">ON THE ROAD</div><h2>${esc(active.title)}</h2><p>${active.stops.filter(x=>x.done).length}/${active.stops.length} cities played · ${esc(active.venue.name)} · ${money(active.ticket)} tickets</p><progress value="${active.stops.filter(x=>x.done).length}" max="${active.stops.length}"></progress><p>${tourNextText(active)} Scheduled shows use energy, but no weekly actions.</p>${activePaceControl(active)}<button onclick="cancelTour('${active.id}')" ${s.retired?'disabled':''}>Cancel remaining dates</button></div>`:''}<div class="card"><div class="eyebrow">TOUR PLANNER</div><h2 style="margin-top:10px">Choose the rooms you want to fill.</h2><p class="muted">Play up to 16 shows per month, in route order. Split a long tour into legs with rest months between them. The standard pace is 8 shows per month. Estimates include venues, travel, crew and management. A half-empty arena can lose money.</p>${releaseOptions.length?`<div class="grid"><div><label>Tour name<input maxlength="70" value="${esc(tourDraft.title)}" oninput="tourDraft.title=this.value"></label><label>Era<select onchange="tourDraft.album=this.value">${releaseOptions.map(a=>`<option value="${a.id}" ${tourDraft.album===a.id?'selected':''}>${esc(a.title)}</option>`).join('')}</select></label><label>Venue size<select onchange="tourDraft.venue=Number(this.value);tourDraft.setlist=null;render()">${VENUES.map((v,i)=>`<option value="${i}" ${tourDraft.venue===i?'selected':''}>${v.name} · ${num(v.cap)} seats</option>`).join('')}</select></label><label>Shows per month<select onchange="tourDraft.pace=Number(this.value)">${paceOptions(tourDraft.pace||8)}</select></label><label>Ticket price ($${TOUR_TICKET_MIN}–$${TOUR_TICKET_MAX})<input type="number" min="${TOUR_TICKET_MIN}" max="${TOUR_TICKET_MAX}" value="${tourDraft.ticket}" oninput="tourDraft.ticket=Number(this.value)"></label></div><div>${tourRoutePlanner()}</div></div>${tourItineraryHTML()}${liveTourPlanner()}<button class="primary" onclick="estimateTour()" ${active||s.retired||age()<14?'disabled':''}>Review plan & budget</button><p><small>Booking costs 1 action and a 20% expense deposit. Only one active tour at a time. ${age()<18?'Guardian supervision is included in travel costs.':''}</small></p>`:'<p>Release an album or EP first, then build its tour here.</p><button onclick="show(\'studio\')">Enter the studio</button>'}</div>${s.tours.length?`<div class="card"><h3>Tour history & results</h3>${s.tours.map(t=>`<details ${t.status==='Active'?'open':''}><summary>${esc(t.title)} · ${t.status} · Net ${money(t.net)}</summary><div class="scroll"><table><tr><th>City</th><th>Show date</th><th>Tickets sold</th><th>Net show result</th></tr>${t.stops.map(x=>`<tr><td>${esc(x.city)}${tourLegTag(t,x)}</td><td>${!x.done&&t.status==='Cancelled'?'Cancelled':showDate(x)}</td><td>${x.done?x.sold+' / '+t.venue.cap:'Scheduled'}</td><td>${x.done?money(x.profit):'—'}</td></tr>`).join('')}</table></div><p class="footnote">Tour net includes all deposits paid. Final show results include each show’s full costs.</p></details>`).join('')}</div>`:''}`;if(!tourDraft.album&&releaseOptions.length)tourDraft.album=releaseOptions[0].id}
// tourCity() now lives in touring-plus.js (legs, higher stop limit).
function tourDemand(city,venue,ticket){return Math.round(cap((18+Math.pow(s.fans,.62)*.85)*city[2]*(.65+s.voice/140)*(.75+s.rep/200)*Math.pow(30/ticket,.8),0,venue.cap))}
function bookTour(){if(!tourPreview||s.tours.some(t=>t.status==='Active')||age()<14)return;let p=tourPreview;closeModal();let album=s.albums.find(a=>a.id===p.album),funding=labelFunding(s.contracts.find(d=>d.id===album?.contract),p.deposit,'tour');if(!canAct(funding.cash))return;useLabelFunding(funding,p.title);s.cash-=funding.cash;s.ap--;let t={...p,id:uid('tour'),status:'Active',net:-funding.cash,labelSupport:funding.credit,started:s.month};s.tours.unshift(t);tourPreview=null;log('Tour booked',`${t.title}: ${t.stops.map(x=>x.city).join(', ')}. ${money(funding.cash)} deposit from you, ${money(funding.credit)} from label funds; estimated net ${money(t.expected)}.`);say(`Your tour is booked at ${t.pace} shows per month. The first leg plays next month. Keep enough cash and energy for the road.`)}
function cancelTour(id){let t=s.tours.find(t=>t.id===id);if(!t||t.status!=='Active'||s.retired)return;modal(`<h2>Cancel the remaining dates?</h2><p>Deposits are not refunded. Reputation −4. Shows already played remain in your history.</p><button onclick="confirmCancelTour('${id}')">Cancel remaining tour</button> <button onclick="closeModal()">Keep the dates</button>`)}function confirmCancelTour(id){let t=s.tours.find(t=>t.id===id);if(!t)return;t.status='Cancelled';change({rep:-4});log('A tour cut short',`You cancelled the remaining dates of ${t.title}.`);closeModal();say('Remaining tour dates cancelled. The deposits have already been paid.')}
const SHOWS=[{id:'meridian',name:'Meridian Music Awards',equiv:'Grammy-style · Craft & recording excellence',month:1,categories:[['Album of the Year','album'],['Song of the Year','song'],['Record of the Year','song']]},{id:'prairie',name:'Prairie Country Awards',equiv:'Country music awards · Country & Americana',month:9,categories:[['Country Album of the Year','album'],['Country Song of the Year','song'],['Country Crossover Song','song']]},{id:'audience',name:'Audience Choice Music Awards',equiv:'AMA-style · Audience popularity',month:10,categories:[['Favourite Album','album'],['Favourite Song','song'],['Breakthrough Song','song']]},{id:'prism',name:'Prism Video Awards',equiv:'VMA-style · Music video achievement',month:7,categories:[['Video of the Year','video'],['Best Direction','video'],['Breakthrough Video','video']]}];
function ceremony(show){let m=Math.floor(s.month/12)*12+show.month;while(m-1<=s.month)m+=12;return m}
function processAwards(){for(let e of s.awardEntries){if(e.status==='Submitted'&&s.month>=e.at-1){let score=entryScore(e),chance=cap((score-30)/100,.05,.72);if(Math.random()<chance){e.status='Nominated';e.nominated=true;change({buzz:3});log('An award nomination',`${e.title} was nominated for ${e.category} at the ${(e.showName||SHOWS.find(x=>x.id===e.show)?.name||e.show)}.`)}else{e.status='Not nominated';log('Submission result',`${e.title} did not receive a nomination for ${e.category} this year.`)}}if(e.status==='Nominated'&&s.month>=e.at){let chance=cap((entryScore(e)-25)/180,.08,.42);if(Math.random()<chance){e.status='Won';s.awards++;change({rep:3,buzz:6});grow(100+Math.min(3000,Math.sqrt(s.fans)*3));log('They called your name',`${e.title} won ${e.category} at the ${(e.showName||SHOWS.find(x=>x.id===e.show)?.name||e.show)}.`)}else{e.status='Nominated · no win';log('Awards night',`${e.title} did not win ${e.category}. The nomination remains part of your career record.`)}}}}
function journal(){ $('view').innerHTML='<div class="card"><h2>The story so far</h2>'+s.log.map(e=>`<div class="entry"><small>${date(e.month)}</small><h3 style="margin:5px 0">${esc(e.title)}</h3><p class="muted">${esc(e.text)}</p></div>`).join('')+'</div>'}
function retire(){if(s.retired)return;modal('<h2>Take your final bow?</h2><p>This ends the career and cancels remaining tour dates. Save first if you might want to return. Your catalogue, awards and timeline remain available.</p><div class="actions"><button onclick="confirmRetire()">Retire</button><button onclick="closeModal()">Keep going</button></div>')}
function confirmRetire(){s.retired=true;s.event=null;for(let t of s.tours)if(t.status==='Active')t.status='Cancelled';log('The final bow','You stepped away from the spotlight on your own terms.');closeModal();render()}
function restart(){modal('<h2>Begin a new life?</h2><p>Your current session will be replaced. Save your game first if you want to keep it.</p><div class="actions"><button onclick="writeBrowserSave();s=null;draft=freshDraft();closeModal();setup()">New life</button><button onclick="closeModal()">Cancel</button></div>')}
function saveGame(){if(!s)return;let blob=new Blob([JSON.stringify({s,draft,tourDraft})],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='liner-notes-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);say('Game exported. Keep the file and use Load to continue later. Browser autosave is separate; keep this export as a portable backup.')}
function migrate(x){let old=x.s;if(old.v===1){old.startAge=18;old.startYear=2026;old.month=old.q*3;old.ap=Math.min(5,old.ap);old.usedEvents=[];old.awardEntries=[];old.tours=[];old.exes=[];old.met=[];old.candidates=[];old.lastActions={};old.legacyAwards=old.awards||0;old.lastRelease=-100;old.albums=old.albums.map(a=>{let month=(a.q||0)*3;old.lastRelease=Math.max(old.lastRelease,month);return {...a,id:uid('album'),month,genres:[a.genre||'Pop'],tracks:a.tracks.map((t,i)=>({id:uid('song'),title:typeof t==='string'?t:t.title,single:i===a.lead,quality:a.quality,released:i===a.lead?month:null,firstStreams:i===a.lead?Math.round(a.streams*.3):0,total:i===a.lead?Math.round(a.total*.3):0,video:null}))}});old.log=old.log.map(e=>({...e,month:(e.q||0)*3}));if(old.relationship)old.relationship={name:typeof old.relationship==='string'?old.relationship:old.relationship.name,bio:'a familiar companion from your earlier chapters',ageAtMeet:18+Math.floor(old.month/12),since:old.month,bond:60,lastDate:old.month};old.contracts=old.contracts||[];if(old.deal&&!old.contracts.some(d=>d.id===old.deal.id))old.contracts.push(old.deal);old.event=null;old.fans=Math.min(FAN_CAP,old.fans);old.v=2;old.log.unshift({month:old.month,title:'A new rhythm',text:'Your quarterly save moved to monthly play. Historical dates were mapped from quarters into months, beginning in 2026. Old money and catalogue results were preserved; unique fans were capped at 200 million. New releases and income use the rebalanced rules.'});x.draft={...x.draft,genres:[x.draft.genre||'Pop'],tracks:(x.draft.tracks||[]).map((t,i)=>({title:typeof t==='string'?t:t.title,single:i===(x.draft.lead||0)}))}}if(old.deal){let d=old.contracts.find(d=>d.id===old.deal.id);if(d)old.deal=d}return migrateToWeekly(x)}
function validateSave(x){if(!x||!x.s||![1,2,3].includes(x.s.v))throw Error('version');let z=x.s;if(typeof z.name!=='string'||!Array.isArray(z.albums)||!Array.isArray(z.log)||!x.draft||!Array.isArray(x.draft.tracks))throw Error('shape');for(let k of ['cash','fans','craft','voice','energy','happiness','rep','buzz','prep','promo','ap'])if(!Number.isFinite(z[k])||Math.abs(z[k])>1e18)throw Error(k);if(z.v>=2&&(z.birthYear!==undefined||z.birthMonth!==undefined)&&(!Number.isInteger(z.birthYear)||!Number.isInteger(z.birthMonth)||z.birthMonth<0||z.birthMonth>11||Math.floor((z.startYear*12-z.birthYear*12-z.birthMonth)/12)!==z.startAge))throw Error('birthday');if(z.v===1&&!Number.isInteger(z.q))throw Error('q');if(z.v===3&&(!Number.isInteger(z.weekStart)||!Number.isInteger(z.birthDay)||z.birthDay<1||z.birthDay>31))throw Error('weeks');if(z.v>=2&&(!Number.isInteger(z.month)||z.month<0||!Number.isInteger(z.startYear)||!Number.isInteger(z.startAge)||!Array.isArray(z.contracts)||!Array.isArray(z.awardEntries)||!Array.isArray(z.tours)||!Array.isArray(z.usedEvents)))throw Error('calendar');for(let a of z.albums){if(z.v>=2&&(!/^[a-zA-Z0-9_-]+$/.test(a.id)||!Array.isArray(a.genres)||a.tracks.some(t=>typeof t.title!=='string'||!/^[a-zA-Z0-9_-]+$/.test(t.id))))throw Error('tracks');if(typeof a.title!=='string'||!Array.isArray(a.tracks)||!/^#[0-9a-f]{6}$/i.test(a.color)||!Number.isFinite(a.total)||!Number.isFinite(a.quality))throw Error('album')}if(z.v>=2&&z.tours.some(t=>!/^[a-zA-Z0-9_-]+$/.test(t.id)||!Array.isArray(t.stops)))throw Error('tour');if(!/^#[0-9a-f]{6}$/i.test(x.draft.color))throw Error('colour');return true}
function loadGame(){let inp=document.createElement('input');inp.type='file';inp.accept='.json';inp.onchange=async()=>{let previous=s,previousDraft=draft,previousTour=tourDraft;try{if(!inp.files[0])return;let x=JSON.parse(await inp.files[0].text());validateSave(x);let wasOld=x.s.v===1,wasMonthly=x.s.v===2;x=migrate(x);s=x.s;ensureCareer();draft=x.draft;tourDraft=x.tourDraft||{title:'',album:'',cities:[],venue:0,ticket:25};tab='life';notice=wasMonthly?'Your save moved to weekly play. Your money, catalogue and fans are unchanged.':wasOld?'Old save upgraded to monthly play. Your money and catalogue are preserved; fan counts now obey the 200 million ceiling. See the timeline for date conversion details.':'Welcome back. Your story continues.';render()}catch{s=previous;draft=previousDraft;tourDraft=previousTour;modal('<h2>Could not load this save</h2><p>Choose a valid Liner Notes JSON save exported by the game. Your current game has not been replaced.</p><button onclick="closeModal()">Close</button>')}};inp.click()}
function relationships(){ $('view').innerHTML=`<div class="card"><div class="row"><h3>Relationships</h3><span class="pill">${s.relationship?'In a relationship':'Single'}</span></div>${s.relationship?`<p>${esc(s.relationship.name)}, ${s.relationship.ageAtMeet+Math.floor((s.month-s.relationship.since)/12)} · ${esc(s.relationship.bio)}</p><p class="muted">Closeness ${s.relationship.bond}/100 · Together since ${MONTHS[s.relationship.since%12]} ${year(s.relationship.since)}</p><div class="actions"><button onclick="datePartner()" ${s.ap<1||s.retired?'disabled':''}>Plan a date · $40</button><button onclick="breakup()" ${s.ap<1||s.retired?'disabled':''}>End the relationship</button></div>`:`<p class="muted">${age()<14?'Friendships first. Dating becomes available at 14.':'Meet someone with a life beyond your release schedule. You choose whether to date.'}</p><button onclick="meetPeople()" ${age()<14||s.ap<1||s.retired?'disabled':''}>Meet new people · 1 action</button>${s.candidates.length?`<div class="grid" style="margin-top:15px">${s.candidates.map((p,i)=>btn(p.name+' · Age '+p.ageAtMeet,p.bio,`choosePartner(${i})`,s.retired)).join('')}</div>`:''}`}</div>`+relationshipHistory();}

setup();

function ensureBirthday(){if(s.birthYear===undefined&&s.birthMonth===undefined){s.birthYear=s.startYear-s.startAge;s.birthMonth=0;s.birthdayInferred=true}}
function birthdayPreview(){let y=Number($('startYear').value),by=Number($('birthYear').value),bm=Number($('birthMonth').value),bd=Number($('birthDay')?.value||1),a=Math.floor((y*12-by*12-bm)/12);$('birthdayPreview').textContent=Number.isInteger(y)&&y>=1960&&y<=2100&&Number.isInteger(by)&&Number.isInteger(bm)&&bm>=0&&bm<=11&&a>=12&&a<=30?`Your story begins in the first week of January ${y}, aged ${a-((bm===0&&bd>3)?1:0)}. You turn a year older on ${bd} ${MONTHS[bm]}. The game runs week by week.`:'Choose a birth month and year that make you 12–30 in January of your starting year.'}

function worldModeHint(){ $('worldModeHint').textContent=$('worldMode').value==='realistic'?'For best historical results, choose an earlier starting year, such as 1990–2010. Realistic mode uses curated, mainly US historical trends and era-appropriate peers. Some dates are approximate. Your choices can change history; after 2026, events are speculative. Your matching artist is removed.':'Fictional mode creates original artists whose careers evolve alongside yours.'}
